#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    int p = 1;
    #pragma omp parallel
    {
        #pragma omp single
        { p = omp_get_num_threads(); }
    }
    if (p > n) p = n;

    std::vector<long long> blockSums(p, 0);
    std::vector<long long> blockOffsets(p + 1, 0);

    // Phase 1: compute per-block reverse prefix sums locally + block totals
    #pragma omp parallel num_threads(p)
    {
        const int tid = omp_get_thread_num();
        const int start = (tid * n) / p;
        const int end   = ((tid + 1) * n) / p; // exclusive
        const int len = end - start;

        long long run = 0;
        // write each output index exactly once by its owning thread
        for (int k = 0; k < len; ++k) {
            const int i = end - 1 - k; // traverse this block from right to left
            run += x[i];
            output[i] = static_cast<int>(run);
        }
        blockSums[tid] = run; // total sum of this block
    }

    // Phase 2: compute offsets (sum of blocks strictly to the right)
    blockOffsets[p] = 0;
    for (int b = p - 1; b >= 0; --b) {
        blockOffsets[b] = blockOffsets[b + 1] + blockSums[b];
    }

    // Phase 3: add each block's right-side offset to its outputs
    #pragma omp parallel num_threads(p)
    {
        const int tid = omp_get_thread_num();
        const int start = (tid * n) / p;
        const int end   = ((tid + 1) * n) / p; // exclusive
        const long long off = blockOffsets[tid + 1]; // sum of blocks to the right

        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + off);
        }
    }
}
